                        .pending_interactive_replay
                        .should_replay_snapshot_request(request),
                    ThreadBufferedEvent::Notification(_)
                    | ThreadBufferedEvent::HistoryEntryResponse(_) => true,
                })
                .cloned()
                .collect(),
            input_state: self.input_state.clone(),
